    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    colors = {v for row in grid for v in row if v != bg}
    if not colors:
        return out
    color = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    h, w = len(grid), len(grid[0])
    # Mark missing cells in horizontal and vertical strokes, between matching
    # colored cells on the same line.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == color]
        for a, b in zip(cs, cs[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == color]
        for a, b in zip(rs, rs[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
